import React, { useState } from 'react';

const styles = {
  header: {
    // A dark background to match the hero section's aesthetic
    backgroundColor: '#1a202c',
    // Default text color for the header
    color: '#e2e8f0',
    padding: '20px 40px',
    // A subtle border to separate the sticky header from content
    borderBottom: '1px solid #2d3748',
    // A subtle shadow for dark mode
    boxShadow: '0 2px 4px rgba(0, 0, 0, 0.2)',
    position: 'sticky',
    top: 0,
    zIndex: 1000,
    transition: 'background-color 0.3s ease-in-out',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  titleContainer: {
    display: 'flex',
    flexDirection: 'column',
  },
  title: {
    fontSize: '2.2rem',
    fontWeight: '700',
    margin: 0,
    // Using the vibrant accent teal from the hero page for the brand name
    color: '#a7ffeb',
  },
  subtitle: {
    fontSize: '1.1rem',
    marginTop: '2px',
    fontStyle: 'italic',
    // A lighter grey that is soft but readable on a dark background
    color: '#a0aec0',
  },
  nav: {
    display: 'flex',
    gap: '30px',
  },
  navLink: {
    // Light color for navigation links
    color: '#e2e8f0',
    textDecoration: 'none',
    fontSize: '1rem',
    fontWeight: '500',
    position: 'relative',
    transition: 'color 0.3s ease',
  },
  navLinkHover: {
    // Hovering makes the link pure white for emphasis
    color: '#ffffff',
  },
  navLinkUnderline: {
    position: 'absolute',
    bottom: '-5px',
    left: 0,
    right: 0,
    height: '2px',
    // The underline uses the same vibrant teal for consistency
    backgroundColor: '#a7ffeb',
    transform: 'scaleX(0)',
    transition: 'transform 0.3s ease-in-out',
  },
};

const Header = () => {
  const [hoveredLink, setHoveredLink] = useState(null);

  const handleMouseEnter = (linkName) => {
    setHoveredLink(linkName);
  };

  const handleMouseLeave = () => {
    setHoveredLink(null);
  };

  return (
    <header style={styles.header}>
      <div style={styles.container}>
        <div style={styles.titleContainer}>
          <h1 style={styles.title}>Karpagam Clinic</h1>
          <p style={styles.subtitle}>Your Health, Our Priority</p>
        </div>
        <nav style={styles.nav}>
          {['Home', 'About Us', 'Services', 'Contact Us'].map((text) => (
            <a
              key={text}
              href={`#${text.toLowerCase().replace(' ', '')}`}
              style={{
                ...styles.navLink,
                ...(hoveredLink === text ? styles.navLinkHover : {}),
              }}
              onMouseEnter={() => handleMouseEnter(text)}
              onMouseLeave={handleMouseLeave}
            >
              {text}
              <span
                style={{
                  ...styles.navLinkUnderline,
                  transform: hoveredLink === text ? 'scaleX(1)' : 'scaleX(0)',
                }}
              />
            </a>
          ))}
        </nav>
      </div>
    </header>
  );
};

export default Header;
